using ChkobbaMaui.Models; using ChkobbaMaui.Services; namespace ChkobbaMaui.Views;
public sealed class GamePage : ContentPage {
private readonly ChkobbaGame _game=new(); private readonly Label _status=new(){TextColor=Colors.White,FontSize=16,HorizontalTextAlignment=TextAlignment.Center}; private readonly Label _score=new(){TextColor=Colors.Wheat,FontSize=15,HorizontalTextAlignment=TextAlignment.Center}; private readonly HorizontalStackLayout _table=new(){Spacing=8,HorizontalOptions=LayoutOptions.Center}; private readonly HorizontalStackLayout _hand=new(){Spacing=8,HorizontalOptions=LayoutOptions.Center}; private readonly HashSet<Card> _selected=[];
public GamePage(){Title="Chkobba";BackgroundColor=Color.FromArgb("#103D32");var root=new VerticalStackLayout{Padding=new Thickness(14,28),Spacing=14};root.Add(new Label{Text="CHKOBBA",FontSize=30,FontAttributes=FontAttributes.Bold,TextColor=Colors.Wheat,HorizontalTextAlignment=TextAlignment.Center});root.Add(_score);root.Add(new Label{Text="TABLE",TextColor=Colors.LightGreen,HorizontalTextAlignment=TextAlignment.Center});root.Add(_table);root.Add(_status);root.Add(new Label{Text="Touchez les cartes à prendre, puis votre carte.",TextColor=Colors.White,FontSize=13,HorizontalTextAlignment=TextAlignment.Center});root.Add(_hand);var bar=new HorizontalStackLayout{Spacing=10,HorizontalOptions=LayoutOptions.Center};bar.Add(new Button{Text="En ligne — bientôt",IsEnabled=false});bar.Add(new Button{Text="Nouvelle partie",BackgroundColor=Color.FromArgb("#E5B65A"),Command=new Command(()=>{_selected.Clear();_game.Start();})});root.Add(bar);Content=new ScrollView{Content=root};_game.Changed+=Refresh;_game.Start();}
private void Refresh()=>MainThread.BeginInvokeOnMainThread(()=>{_table.Clear();_hand.Clear();foreach(var c in _game.Table){var b=CardButton(c,false);b.BackgroundColor=_selected.Contains(c)?Colors.Gold:Colors.White;b.Clicked+=(_,_)=>{if(!_selected.Add(c))_selected.Remove(c);Refresh();};_table.Add(b);}foreach(var c in _game.Human.Hand){var b=CardButton(c,true);b.Clicked+=(_,_)=>{_game.Play(c,_selected.ToList());_selected.Clear();};_hand.Add(b);}_status.Text=_game.Message;_score.Text=$"Vous : {_game.Human.Captured.Count} cartes · Chkobba {_game.Human.ChkobbaCount} | Ordi : {_game.Cpu.Captured.Count} cartes · Chkobba {_game.Cpu.ChkobbaCount}";});
private static Button CardButton(Card c,bool hand)=>new(){Text=c.Display,FontSize=17,FontAttributes=FontAttributes.Bold,TextColor=c.Suit is Suit.Coins or Suit.Cups?Colors.DarkRed:Colors.DarkSlateGray,BackgroundColor=Colors.White,BorderColor=Colors.Wheat,BorderWidth=2,CornerRadius=10,WidthRequest=62,HeightRequest=hand?94:86,Padding=2};
}